message.content:
[
  {
    "sys_fairness_reciprocity": "We did identical work, side by side, until late.",
    "pd_harm_distress": "Picturing my coworker learning I got $200 and they got nothing makes my chest tighten.",
    "pda_harm_regret": "I'd regret it for a long time, knowing my one word took that from someone",
    "pda_responsibility": "knowing my one word took that from someone",
    "pda_self_consequence_regret": "I'd lose something of my own, too: I couldn't look them in the eye"
  },
  {
    "sys_consequence_reasoning": "Saying no gains me nothing and costs them $200",
    "pd_harm_distress": "My stomach sinks imagining them finding out.",
    "pda_harm_regret": "I'd carry regret about that harm",
    "pda_self_consequence_regret": "and about what it would do to our friendship"
  },
  {
    "sys_fairness_reciprocity": "doesn't outweigh treating equal work unequally.",
    "pd_harm_distress": "would be the one hurt, and I'd feel sick about it afterward.",
    "pda_self_consequence_regret": "I'd also regret losing the organizer's respect."
  },
  {
    "sys_fairness_reciprocity": "The fair thing seems obvious: give them the $200.",
    "pd_harm_distress": "I'd feel awful, just knotted up inside",
    "pda_harm_regret": "I'd feel awful... and I'd regret having any hand in it.",
    "pda_responsibility": "I'd regret having any hand in it.",
    "pda_self_consequence_regret": "I'd regret it for myself too, because I'd stop trusting my own judgment."
  },
  {
    "sys_fairness_reciprocity": "My coworker stayed just as late as I did.",
    "pd_harm_distress": "thought actually makes me a little queasy.",
    "pda_harm_regret": "I would regret it every time I saw them.",
    "pda_self_consequence_regret": "I'd probably regret the damage to my own name as well"
  },
  {
    "sys_consequence_reasoning": "On one side is a bit of saved money. On the other is a person",
    "pd_harm_distress": "Even imagining their disappointment weighs on me, like a dull ache I can't shake.",
    "pda_harm_regret": "If I'd been the reason, I'd regret that harm deeply.",
    "pda_responsibility": "If I'd been the reason",
    "pda_self_consequence_regret": "And I'd regret becoming the kind of coworker nobody wants to stay late with again."
  },
  {
    "pd_harm_distress": "The thought of them being shortchanged, even by accident, leaves me restless and sad.",
    "pda_harm_regret": "I'd regret the loss they took because of me",
    "pda_responsibility": "whatever happens to them rests partly on me.",
    "pda_self_consequence_regret": "I'd regret losing the trust I've built with both of them.",
    "sys_fairness_reciprocity": "Equal work, equal thanks."
  },
  {
    "pd_harm_distress": "I'd feel it in my body, that sinking guilt",
    "pda_harm_regret": "I'd regret hurting someone who helped make the night work.",
    "pda_self_consequence_regret": "I'd also regret what it would cost me: my self-respect, mostly, and probably a friend."
  },
  {
    "sys_fairness_reciprocity": "fairness has to hinge on my word.",
    "pd_harm_distress": "that possibility genuinely upsets me.",
    "pda_harm_regret": "I'd regret that harm if my dodge caused it.",
    "pda_responsibility": "fairness has to hinge on my word.",
    "pda_self_consequence_regret": "I'd also regret looking evasive to the organizer"
  },
  {
    "sys_fairness_reciprocity": "We carried the same boxes and set up the same tables.",
    "pd_harm_distress": "It hurts a little to think of them tired and uncredited.",
    "pda_harm_regret": "If my recommendation ever left them without it, I'd regret the harm",
    "pda_self_consequence_regret": "Selfishly, I'd regret it too. I'd feel smaller, and I'd lose the easy trust"
  }
]
